  --color-sunset-amber: #ff8040;
  --color-ink: #000000;
  --color-graphite: #333333;
  --color-slate: #707070;
  --color-cool-gray: #6b7280;
  --color-steel: #7e8389;
  --color-fog: #949494;
  --color-pearl: #dedee0;
  --color-mist: #cccccf;
  --color-paper: #ffffff;
  --color-linen: #f7f7f9;
  --color-ash: #f2f2f2;
  --color-cream: #fff9ed;
  --color-lavender-mist: #eff0ff;
